ALTER TABLE public.profiles ADD COLUMN friend_code text NOT NULL DEFAULT ('NF-' || replace(gen_random_uuid()::text, '-', ''));
CREATE UNIQUE INDEX profiles_friend_code_unique ON public.profiles(friend_code);
CREATE TABLE public.friendships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted')), created_at timestamptz NOT NULL DEFAULT now(), CHECK (requester_id <> recipient_id));
GRANT SELECT ON public.friendships TO authenticated;
GRANT ALL ON public.friendships TO service_role;
ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
CREATE POLICY friendship_own_read ON public.friendships FOR SELECT TO authenticated USING (auth.uid() IN (requester_id,recipient_id));
CREATE UNIQUE INDEX friendship_pair_unique ON public.friendships(least(requester_id,recipient_id),greatest(requester_id,recipient_id));
CREATE FUNCTION public.are_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.friendships WHERE status='accepted' AND ((requester_id=a AND recipient_id=b) OR (requester_id=b AND recipient_id=a))) $$;
REVOKE ALL ON FUNCTION public.are_friends(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.are_friends(uuid,uuid) TO authenticated,service_role;
CREATE POLICY profile_friend_read ON public.profiles FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.friendships f WHERE (f.requester_id=auth.uid() AND f.recipient_id=profiles.id) OR (f.recipient_id=auth.uid() AND f.requester_id=profiles.id)));
CREATE FUNCTION public.request_friend(_code text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT id INTO target FROM public.profiles WHERE friend_code=upper(trim(_code)); IF target IS NULL THEN RAISE EXCEPTION 'Identifiant introuvable'; END IF; IF target=auth.uid() THEN RAISE EXCEPTION 'Vous ne pouvez pas vous ajouter'; END IF; INSERT INTO public.friendships(requester_id,recipient_id) VALUES(auth.uid(),target) ON CONFLICT DO NOTHING RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Une demande ou une amitié existe déjà'; END IF; RETURN result; END $$;
CREATE FUNCTION public.respond_friend(_id uuid,_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _accept THEN UPDATE public.friendships SET status='accepted' WHERE id=_id AND recipient_id=auth.uid() AND status='pending'; ELSE DELETE FROM public.friendships WHERE id=_id AND auth.uid() IN (requester_id,recipient_id); END IF; END $$;
REVOKE ALL ON FUNCTION public.request_friend(text),public.respond_friend(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_friend(text),public.respond_friend(uuid,boolean) TO authenticated;
CREATE TABLE public.friend_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), screening_id uuid REFERENCES public.screenings(id), provider_url text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now()+interval '4 hours'), ended_at timestamptz);
GRANT SELECT ON public.friend_calls TO authenticated;
GRANT ALL ON public.friend_calls TO service_role;
ALTER TABLE public.friend_calls ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.friend_call_members (call_id uuid NOT NULL REFERENCES public.friend_calls(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, state text NOT NULL DEFAULT 'invited' CHECK(state IN ('invited','joined','left','declined')), PRIMARY KEY(call_id,user_id));
GRANT SELECT ON public.friend_call_members TO authenticated;
GRANT ALL ON public.friend_call_members TO service_role;
ALTER TABLE public.friend_call_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_call_member(_call uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.friend_call_members WHERE call_id=_call AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_call_member(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_call_member(uuid) TO authenticated;
CREATE POLICY calls_invited_read ON public.friend_calls FOR SELECT TO authenticated USING (public.is_call_member(id));
CREATE POLICY call_members_read ON public.friend_call_members FOR SELECT TO authenticated USING (public.is_call_member(call_id));
CREATE POLICY profile_call_peer_read ON public.profiles FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.friend_call_members m WHERE m.user_id=profiles.id AND public.is_call_member(m.call_id)));
CREATE FUNCTION public.create_friend_call(_friends uuid[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; friend uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF coalesce(cardinality(_friends),0)<1 OR cardinality(_friends)>7 THEN RAISE EXCEPTION 'Choisissez de 1 à 7 amis'; END IF; FOREACH friend IN ARRAY _friends LOOP IF friend=auth.uid() OR NOT public.are_friends(auth.uid(),friend) THEN RAISE EXCEPTION 'Appel réservé aux amis acceptés'; END IF; END LOOP; INSERT INTO public.friend_calls(owner_id) VALUES(auth.uid()) RETURNING id INTO result; INSERT INTO public.friend_call_members(call_id,user_id,state) VALUES(result,auth.uid(),'joined'); INSERT INTO public.friend_call_members(call_id,user_id) SELECT result,unnest(_friends) ON CONFLICT DO NOTHING; RETURN result; END $$;
CREATE FUNCTION public.respond_friend_call(_call uuid,_state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _state NOT IN ('joined','left','declined') THEN RAISE EXCEPTION 'Invalid state'; END IF; PERFORM 1 FROM public.friend_calls WHERE id=_call AND ended_at IS NULL AND expires_at>now() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Appel terminé'; END IF; UPDATE public.friend_call_members SET state=_state WHERE call_id=_call AND user_id=auth.uid() AND ((_state='joined' AND state IN ('invited','joined')) OR (_state IN ('left','declined') AND state IN ('invited','joined'))); IF NOT FOUND THEN RAISE EXCEPTION 'Accès refusé'; END IF; IF NOT EXISTS(SELECT 1 FROM public.friend_call_members WHERE call_id=_call AND state='joined') THEN UPDATE public.friend_calls SET ended_at=now() WHERE id=_call; END IF; END $$;
CREATE FUNCTION public.share_call_screening(_call uuid,_screening uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.friend_call_members WHERE call_id=_call AND user_id=auth.uid() AND state='joined') THEN RAISE EXCEPTION 'Accès refusé'; END IF; IF _screening IS NOT NULL AND NOT public.can_enter_screening(_screening) THEN RAISE EXCEPTION 'Cette séance nécessite un accès'; END IF; UPDATE public.friend_calls SET screening_id=_screening WHERE id=_call AND ended_at IS NULL AND expires_at>now(); END $$;
REVOKE ALL ON FUNCTION public.create_friend_call(uuid[]),public.respond_friend_call(uuid,text),public.share_call_screening(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_friend_call(uuid[]),public.respond_friend_call(uuid,text),public.share_call_screening(uuid,uuid) TO authenticated;